import { useQuery, type UseQueryOptions } from "@tanstack/react-query";
import { listUserReports } from "../handlers/listUserReports";
import type { ApiError } from "../runtime/client";

type Data = Awaited<ReturnType<typeof listUserReports>>;

export function useListUserReports(
  userId: string,
  bookmark?: string | null,
  options?: Omit<UseQueryOptions<Data, ApiError>, "queryKey" | "queryFn">,
) {
  return useQuery<Data, ApiError>({
    queryKey: ["listUserReports", userId, bookmark],
    queryFn: () => listUserReports(userId, bookmark),
    ...options,
  });
}
